using STS2RitsuLib.Scaffolding.Cards.HandOutline;

namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private static int _taskHandPatchUnknownCalls;
    private static void TaskHandPatchUnknownPrefix()=>_taskHandPatchUnknownCalls++;
    private sealed class TaskHandRuleComparer : IEqualityComparer<Type>
    {
        public bool Equals(Type? x,Type? y){_taskHandPatchUnknownCalls++;return ReferenceEquals(x,y);}
        public int GetHashCode(Type x){_taskHandPatchUnknownCalls++;return x.GetHashCode();}
    }
    private async Task AssertTaskHandPatchSourcesAsync(CombatState live,Player player)
    {
        SetStage("task_hand_patch_sources");
        await CreatureCmd.SetMaxHp(player.Creature,75);await CreatureCmd.SetCurrentHp(player.Creature,60);
        foreach(var potion in player.PotionSlots.ToArray())potion?.Discard();
        for(int i=0;i<4;i++)await NGame.Instance!.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
        var first=TaskHandPatchSources.Capture();
        if(!first.ExtensionSourcesClosed)throw new InvalidOperationException("Ordinary extension layer refused: "+JsonSerializer.Serialize(first));
        var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();
        string Stamp(CombatPredictionSimulator sim)=>DescribeContinuationContractState(sim,root,player);
        string parentBefore=Stamp(parent),liveBefore=ContinuationStamp.CaptureLive(live).StateText;
        var actual=live.Enemies.Select(e=>CaptureActual(live,player,e)).ToArray();
        const BindingFlags flags=TaskHandPatchSources.Flags;
        Type Runtime(string n)=>TaskHandPatchSources.RuntimeType(n);
        FieldInfo Field(Type t,string n)=>TaskHandPatchSources.Field(t,n);
        MethodInfo Method(Type t,string n)=>t.GetMethods(flags).Single(m=>m.Name==n);
        var extra=Runtime("STS2RitsuLib.CardPiles.Patches.ModExtraHandCardVisualSemanticPatch");
        var outlinePatch=Runtime("STS2RitsuLib.Scaffolding.Cards.HandOutline.Patches.NHandCardHolderUpdateCardHandOutlinePatch");
        var outline=Runtime("STS2RitsuLib.Scaffolding.Cards.HandOutline.ModCardHandOutlineRegistry");
        var content=Runtime("STS2RitsuLib.Content.ModContentRegistry");var piles=Runtime("STS2RitsuLib.CardPiles.ModCardPileRegistry");
        var context=Runtime("STS2RitsuLib.CardPiles.ModExtraHandSemanticContext");
        var holder=NPlayerHand.Instance!.Holders.First(h=>h.CardNode is not null);
        object?[] prefixArgs=[holder,null];
        Method(extra,"Prefix").Invoke(null,prefixArgs);
        if(prefixArgs[1] is not null)throw new InvalidOperationException("Native extra-hand prefix unexpectedly created scope.");
        Method(outlinePatch,"Postfix").Invoke(null,[holder]);Method(extra,"Finalizer").Invoke(null,[prefixArgs[1]]);
        for(int i=0;i<actual.Length;i++)AssertSnapshotEqual(CaptureActual(live,player,live.Enemies[i]),actual[i],"HandExtensionPatches","ThreeDirectNativeNoOps");
        if(Stamp(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore)
            throw new InvalidOperationException("Native patch invocation changed combat state/history/RNG.");
        _taskHandPatchUnknownCalls=0;bool armed=false,healed=false;int ruleCalls=0;
        Color? UnknownColor(CardModel card)
        {
            ruleCalls++;
            if(armed&&!healed&&player.Creature.CurrentHp<60){healed=true;player.Creature.HealInternal(2);}
            return null;
        }
        object rules=Field(outline,"RulesByCardType").GetValue(null)!;Type rulesType=rules.GetType();
        var dictionary=(IDictionary)rules;Type entryType=outline.GetNestedType("RegisteredRule",BindingFlags.NonPublic)!;
