namespace CombatSolver;

// This closes the rule/extra-pile extension source layer. Native UI queries,
// card pile traversal/equality, visual hooks and the whole HP chain remain separate.
internal static class TaskHandPatchSources
{
    internal const BindingFlags Flags=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.DeclaredOnly;
    private static readonly Guid RitsuMvid=new("f7f18a36-8ebb-4db2-b1ea-7bd340579646");
    private static readonly Guid GameMvid=new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    internal sealed record Result(bool ExtensionSourcesClosed,ImmutableArray<string> Refusals,
        bool ContentFrozen,bool PilesFrozen,int RuleTypeCount,int PileTypeCount,int HasAnyFlag,
        bool AmbientContextEmpty,bool DefaultRuleComparer,bool DefaultPileComparer,
        ImmutableArray<string> UnprovenLowerBoundaries,bool WholeHealthCertificate=false);
    internal static FieldInfo Field(Type t,string n)=>t.GetField(n,Flags)
        ??throw new InvalidOperationException("Hand extension field contract changed: "+t.FullName+"."+n);
    internal static Type RuntimeType(string n)=>typeof(HealHook).Assembly.GetType(n,true)!;
    internal static bool Patched(MethodBase m)
    {
        var p=Harmony.GetPatchInfo(m);return p is not null&&p.Prefixes.Count+p.Postfixes.Count+p.Transpilers.Count+p.Finalizers.Count!=0;
    }
    internal static Result Capture()
    {
        var reasons=ImmutableArray.CreateBuilder<string>();
        var lower=ImmutableArray.Create("native-ui-query-and-model-getter-closure","native-player-pile-and-card-equality-closure",
            "vanilla-card-visual-cost-hook-and-signal-closure","future-hand-visual-and-selection-source-closure");
        if(typeof(CardModel).Module.ModuleVersionId!=GameMvid||typeof(HealHook).Module.ModuleVersionId!=RitsuMvid)
            throw new InvalidOperationException("Unaudited hand extension versions.");
        var outline=RuntimeType("STS2RitsuLib.Scaffolding.Cards.HandOutline.ModCardHandOutlineRegistry");
        var content=RuntimeType("STS2RitsuLib.Content.ModContentRegistry");
        var piles=RuntimeType("STS2RitsuLib.CardPiles.ModCardPileRegistry");
        var context=RuntimeType("STS2RitsuLib.CardPiles.ModExtraHandSemanticContext");
        var extra=RuntimeType("STS2RitsuLib.CardPiles.Patches.ModExtraHandCardVisualSemanticPatch");
        var color=RuntimeType("STS2RitsuLib.Scaffolding.Cards.HandOutline.Patches.NHandCardHolderUpdateCardHandOutlinePatch");
        var helper=RuntimeType("STS2RitsuLib.Scaffolding.Cards.HandOutline.Patches.ModCardHandOutlinePatchHelper");
        MethodInfo Method(Type t,string n)=>t.GetMethods(Flags).Single(m=>m.Name==n);
        var prefix=Method(extra,"Prefix");var finalizer=Method(extra,"Finalizer");var postfix=Method(color,"Postfix");
        var update=AccessTools.Method(typeof(NHandCardHolder),"UpdateCard");var combination=Harmony.GetPatchInfo(update);
        if(combination is null||combination.Prefixes.Count!=1||combination.Postfixes.Count!=1||combination.Transpilers.Count!=0
            ||combination.Finalizers.Count!=1||combination.Prefixes[0].PatchMethod!=prefix
            ||combination.Postfixes[0].PatchMethod!=postfix||combination.Finalizers[0].PatchMethod!=finalizer)
            reasons.Add("patch:update-card-combination");
        foreach(var method in new[]{prefix,postfix,finalizer,Method(context,"EnterPlayEvaluation"),Method(context,"IsActive"),
            Method(helper,"TryGetRule"),Method(helper,"TryGetCardModel"),Method(helper,"IsHolderUsable"),
            Method(outline,"EvaluateBest"),AccessTools.Method(piles,"TryGetByPileType"),
            AccessTools.PropertyGetter(typeof(CardModel),"Pile")})
        {
            // The installed CombatSolver Pile prefix is only recorded as a lower
            // boundary here; it is not silently certified by this extension layer.
            if(method.DeclaringType==typeof(CardModel))continue;
            if(Patched(method))reasons.Add("patch:"+method.DeclaringType!.FullName+"."+method.Name);
        }
        bool frozen;object contentLock=Field(content,"SyncRoot").GetValue(null)!;
        if(contentLock is not System.Threading.Lock)throw new InvalidOperationException("Unknown content registration lock.");
        using(((System.Threading.Lock)contentLock).EnterScope())frozen=(bool)Field(content,"<IsFrozen>k__BackingField").GetValue(null)!;
        if(!frozen)reasons.Add("content-not-frozen");
        object rules=Field(outline,"RulesByCardType").GetValue(null)!;
        Type rulesType=rules.GetType();Type registered=outline.GetNestedType("RegisteredRule",BindingFlags.NonPublic)!;
        Type expectedRules=typeof(System.Collections.Concurrent.ConcurrentDictionary<,>).MakeGenericType(typeof(Type),typeof(List<>).MakeGenericType(registered));
        if(rulesType!=expectedRules)throw new InvalidOperationException("Unknown rule registry shape.");
        PropertyInfo ruleComparerProperty=rulesType.GetProperty("Comparer")!;
        if(Patched(ruleComparerProperty.GetMethod!))throw new PredictionUnsupportedException("patch:rule-comparer-getter");
        if(Patched(rulesType.GetProperty("Count")!.GetMethod!))throw new PredictionUnsupportedException("patch:rule-count-getter");
        object comparer=ruleComparerProperty.GetValue(rules)!;
        bool defaultRules=ReferenceEquals(comparer,EqualityComparer<Type>.Default);
        if(!defaultRules)reasons.Add("unknown-rule-comparer");
        // Count acquires CLR dictionary locks and does not call the key comparer.
        int ruleCount=((ICollection)rules).Count;
        if(ruleCount!=0)reasons.Add("outline-rule-types:"+ruleCount);
        int flag=(int)Field(outline,"_hasAny").GetValue(null)!;
        object pileLock=Field(piles,"SyncRoot").GetValue(null)!;
        if(pileLock is not System.Threading.Lock)throw new InvalidOperationException("Unknown pile registration lock.");
        bool pileFrozen,defaultPiles;int pileCount;
        using(((System.Threading.Lock)pileLock).EnterScope())
        {
            pileFrozen=(bool)Field(piles,"<IsFrozen>k__BackingField").GetValue(null)!;
            object definitions=Field(piles,"DefinitionsByPileType").GetValue(null)!;
            Type expected=typeof(Dictionary<,>).MakeGenericType(typeof(PileType),RuntimeType("STS2RitsuLib.CardPiles.ModCardPileDefinition"));
            if(definitions.GetType()!=expected)throw new InvalidOperationException("Unknown pile lookup shape.");
            var getter=expected.GetProperty("Comparer")!.GetMethod!;
            if(Patched(getter))throw new PredictionUnsupportedException("patch:pile-comparer-getter");
            if(Patched(expected.GetProperty("Count")!.GetMethod!))throw new PredictionUnsupportedException("patch:pile-count-getter");
            defaultPiles=ReferenceEquals(expected.GetProperty("Comparer")!.GetValue(definitions),EqualityComparer<PileType>.Default);
            pileCount=((IDictionary)definitions).Count;
        }
        if(!pileFrozen)reasons.Add("pile-registration-not-frozen");
        if(!defaultPiles)reasons.Add("unknown-pile-comparer");
        if(pileCount!=0)reasons.Add("extra-pile-types:"+pileCount);
        object current=Field(context,"Current").GetValue(null)!;Type currentType=current.GetType();
        if(!currentType.IsGenericType||currentType.GetGenericTypeDefinition()!=typeof(AsyncLocal<>))
            throw new InvalidOperationException("Unknown extra-hand ambient storage.");
        var value=currentType.GetProperty("Value")!;
        if(Patched(value.GetMethod!))throw new PredictionUnsupportedException("patch:ambient-context-getter");
        bool empty=value.GetValue(current) is null;
        if(!empty)reasons.Add("active-extra-hand-context");
        return new(reasons.Count==0,reasons.ToImmutable(),frozen,pileFrozen,ruleCount,pileCount,flag,empty,
            defaultRules,defaultPiles,lower);
    }
}

