	private static Action<RunState, IReadOnlyList<ActModel>> CreateRunStateActsSetter()
	{
		MethodInfo set = typeof(RunState).GetProperty("Acts", BindingFlags.Instance | BindingFlags.Public)?.GetSetMethod(nonPublic: true) ?? throw new InvalidOperationException("RunState.Acts setter not found.");
		return delegate(RunState rs, IReadOnlyList<ActModel> acts)
