	/// <summary>
	///     <para xml:lang="en">
	///         Registers a rule that replaces <paramref name="slotIndex" /> with
	///         <typeparamref name="TAct" /> when eligible. Higher priority wins, with earlier registration
	///         breaking ties.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册一条在符合条件时将 <paramref name="slotIndex" /> 替换为
	///         <typeparamref name="TAct" /> 的规则。优先级较高者胜出，同优先级时先注册者胜出。
	///     </para>
	/// </summary>
	public void RegisterActEnterForce<TAct>(int slotIndex, int priority, Func<ActEnterResolveContext, bool> eligibility) where TAct : ActModel
	{
		ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
		ArgumentNullException.ThrowIfNull(eligibility, "eligibility");
		EnsureMutable($"register act enter force at slot {slotIndex}");
		EnsureModelType(typeof(TAct), typeof(ActModel), "TAct");
		using (SyncRoot.EnterScope())
		{
			EnsureMutable($"register act enter force at slot {slotIndex}");
			int tieBreakOrder = ++_actEnterForceTieBreakSeq;
			ActEnterForces.Add(new ActEnterForceEntry(slotIndex, (ActEnterResolveContext _) => typeof(TAct), priority, tieBreakOrder, eligibility));
			Interlocked.Increment(ref _actEnterRegistrationCount);
		}
		_logger.Info($"[Content] Registered act enter force: slot {slotIndex} priority {priority} -> {typeof(TAct).Name}", 1);
	}

	public void RegisterActEnterForcePool(int slotIndex, int priority, Func<ActEnterResolveContext, bool> eligibility, params (Type ActType, double Weight)[] candidates)
	{
		ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
		ArgumentNullException.ThrowIfNull(eligibility, "eligibility");
		EnsureMutable($"register act enter force pool at slot {slotIndex}");
		(Type, double)[] source = PrepareActEnterForceCandidates(candidates);
		KeyValuePair<Type, double>[] weighted = source.Select(((Type ActType, double Weight) candidate) => new KeyValuePair<Type, double>(candidate.ActType, candidate.Weight)).ToArray();
		using (SyncRoot.EnterScope())
		{
			EnsureMutable($"register act enter force pool at slot {slotIndex}");
			int tieBreakOrder = ++_actEnterForceTieBreakSeq;
			ActEnterForces.Add(new ActEnterForceEntry(slotIndex, (ActEnterResolveContext ctx) => ActEnterPool<ActEnterResolveContext, Type>.SelectWeighted(weighted, () => ctx.Rng.NextDouble()), priority, tieBreakOrder, eligibility));
			Interlocked.Increment(ref _actEnterRegistrationCount);
		}
		_logger.Info($"[Content] Registered act enter force pool: slot {slotIndex} priority {priority}, {weighted.Length} candidates", 1);
	}

	internal static (Type ActType, double Weight)[] PrepareActEnterForceCandidates((Type ActType, double Weight)[] candidates)
	{
		return ActEnterPool<ActEnterResolveContext, Type>.PrepareForcedCandidates(candidates, delegate(Type type)
		{
			EnsureModelType(type, typeof(ActModel), "candidates");
		}, GetActEnterCandidateKey);
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Declares this mod's uniform contributions to a zero-based slot before content freezes. Repeating the
	///         declaration is harmless; switching this mod's mode throws. Other mods may use weighted candidates in the
	///         same slot. Uniform candidates contribute weight 1, and the existing act always has fixed weight 1.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在内容冻结前为本模组声明从零开始的槽位的均匀候选。重复声明无影响，切换本模组的模式会抛出异常。其他模组可在同一槽位使用加权候选。均匀候选与已有章节均以权重 1 参与抽选，已有章节的权重不可修改。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Registrations remain active for the process lifetime; there is no per-run registration or removal.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册在进程存续期间有效，不提供每局注册或移除。
	///     </para>
	/// </remarks>
	public void RegisterActEnterUniformPool(int slotIndex)
	{
		ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
		EnsureMutable($"register act enter uniform pool at slot {slotIndex}");
		using (SyncRoot.EnterScope())
		{
			EnsureMutable($"register act enter uniform pool at slot {slotIndex}");
			GetOrCreateActEnterPool(slotIndex).Declare(ModId, ActEnterPoolModeKind.Uniform);
			Interlocked.Increment(ref _actEnterRegistrationCount);
		}
		_logger.Info($"[Content] Registered act enter uniform pool: slot {slotIndex}", 1);
	}

	/// <summary>
	///     <para xml:lang="en">
	///         Adds a weight-1 candidate to this mod's previously declared uniform pool before content freezes.
	///         Registering the same type twice in one mod and slot throws. Different mods' contributions for the same
	///         type merge by maximum eligible weight. Candidates matching the existing act are ignored.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在内容冻结前向本模组已声明的均匀池添加权重为 1 的候选。同一模组在同一槽位重复注册类型会抛出异常；不同模组的同类型候选取最大有效权重。与已有章节相同的候选被忽略。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Registrations remain active for the process lifetime; there is no per-run registration or removal.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册在进程存续期间有效，不提供每局注册或移除。
	///     </para>
	///     <para xml:lang="en">
	///         Callbacks execute outside the registration lock in ordinal, case-insensitive mod-ID order, then ordinal
	///         type-name order. Each runs at most once per resolution, with eligibility before weight. They must be
	///         deterministic and side-effect-free; exceptions propagate before act replacement.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         回调于注册锁外按模组 ID（不区分大小写）、类型名的序数顺序执行，每次解析至多执行一次，先判断条件再计算权重。回调必须确定且无副作用；异常在替换章节前向上传播。
	///     </para>
	/// </remarks>
	public void RegisterActEnterUniformPoolCandidate<TAct>(int slotIndex, Func<ActEnterResolveContext, bool> eligibility) where TAct : ActModel
	{
		ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
		ArgumentNullException.ThrowIfNull(eligibility, "eligibility");
		EnsureMutable($"register act enter uniform pool candidate at slot {slotIndex}");
		EnsureModelType(typeof(TAct), typeof(ActModel), "TAct");
		using (SyncRoot.EnterScope())
		{
			EnsureMutable($"register act enter uniform pool candidate at slot {slotIndex}");
			RequireActEnterPool(slotIndex).AddCandidate(ModId, ActEnterPoolModeKind.Uniform, typeof(TAct), eligibility, (ActEnterResolveContext _) => 1.0);
			Interlocked.Increment(ref _actEnterRegistrationCount);
		}
		_logger.Info($"[Content] Registered act enter uniform pool candidate: slot {slotIndex} -> {typeof(TAct).Name}", 1);
	}

