	internal static void ResolveActEnterForEnterAct(RunManager runManager, RunState runState, int enteringActIndex)
	{
		//IL_0081: Unknown result type (might be due to invalid IL or missing references)
		//IL_0087: Invalid comparison between Unknown and I4
		if (!HasAnyActEnterRegistration || (uint)enteringActIndex >= (uint)runState.Acts.Count)
		{
			return;
		}
		ActEnterForceEntry[] array;
		ActEnterPool<ActEnterResolveContext, Type>.Snapshot snapshot;
		using (SyncRoot.EnterScope())
		{
			array = ActEnterForces.ToArray();
			snapshot = (ActEnterPools.TryGetValue(enteringActIndex, out ActEnterPool<ActEnterResolveContext, Type> value) ? value.CreateSnapshot(GetActEnterCandidateKey) : null);
		}
		bool isMultiplayer = runManager.NetService != null && (int)runManager.NetService.Type != 1;
		ActEnterResolveContext ctx = new ActEnterResolveContext(runManager, runState, enteringActIndex, runState.Rng.Niche, runState.UnlockState, isMultiplayer);
		Array.Sort(array, delegate(ActEnterForceEntry a, ActEnterForceEntry b)
		{
			int num2 = b.Priority.CompareTo(a.Priority);
			return (num2 == 0) ? a.TieBreakOrder.CompareTo(b.TieBreakOrder) : num2;
		});
		ActEnterForceEntry[] array2 = array;
		for (int num = 0; num < array2.Length; num++)
		{
			ActEnterForceEntry actEnterForceEntry = array2[num];
			if (actEnterForceEntry.SlotIndex == enteringActIndex && actEnterForceEntry.Eligibility(ctx))
			{
				Type type = actEnterForceEntry.Select(ctx);
				if (type != ((object)runState.Acts[enteringActIndex]).GetType())
				{
					ReplaceActAtSlot(runManager, runState, enteringActIndex, type);
				}
				return;
			}
		}
		if (snapshot != null)
		{
			Type type2 = ((object)runState.Acts[enteringActIndex]).GetType();
			Type type3 = snapshot.Select(ctx, type2, GetActEnterCandidateKey, () => ctx.Rng.NextDouble());
			if (type3 != type2)
			{
				ReplaceActAtSlot(runManager, runState, enteringActIndex, type3);
			}
		}
	}

	private static string GetActEnterCandidateKey(Type type)
	{
		return type.FullName ?? type.Name;
	}

	private static ActEnterPool<ActEnterResolveContext, Type> GetOrCreateActEnterPool(int slotIndex)
	{
		if (ActEnterPools.TryGetValue(slotIndex, out ActEnterPool<ActEnterResolveContext, Type> value))
		{
			return value;
		}
		value = new ActEnterPool<ActEnterResolveContext, Type>();
		ActEnterPools.Add(slotIndex, value);
		return value;
	}

	private static ActEnterPool<ActEnterResolveContext, Type> RequireActEnterPool(int slotIndex)
	{
		if (!ActEnterPools.TryGetValue(slotIndex, out ActEnterPool<ActEnterResolveContext, Type> value))
		{
			throw new InvalidOperationException($"Slot {slotIndex}: declare an act-entry pool first.");
		}
		return value;
	}

	private static void ReplaceActAtSlot(RunManager runManager, RunState runState, int slotIndex, Type actType)
	{
		ActModel val = runState.Acts[slotIndex];
		List<ActModel> list = runState.Acts.ToList();
		ActModel val2 = ModelDb.GetById<ActModel>(ModelDb.GetId(actType)).ToMutable();
		CopySharedAncientSubset(val, val2);
		list[slotIndex] = val2;
		RunStateActsSetter(runState, list);
		InitializeRoomsForReplacedActIfNeeded(runManager, runState, slotIndex, val);
	}

	private static void CopySharedAncientSubset(ActModel source, ActModel target)
	{
		if (source != target)
		{
			List<AncientEventModel> list = ActSharedAncientSubsetRef.Invoke(source);
			ActSharedAncientSubsetRef.Invoke(target) = list?.ToList();
		}
	}

	private static void InitializeRoomsForReplacedActIfNeeded(RunManager runManager, RunState runState, int actIndex, ActModel actBeforeReplace)
	{
		ActModel act = runState.Acts[actIndex];
		if (act == actBeforeReplace)
		{
			return;
		}
		RequestActEnterPostMapUiMapSyncBump();
		((AbstractModel)act).AssertMutable();
		act.GenerateRooms(runState.Rng.UpFront, runState.UnlockState, runState.Players.Count > 1);
		if (runManager.ShouldApplyTutorialModifications())
		{
			act.ApplyDiscoveryOrderModifications(runState.UnlockState);
		}
		if (actIndex == runState.Acts.Count - 1 && runManager.AscensionManager.HasLevel((AscensionLevel)10))
		{
