	private static bool TryMergeCardPoolAssetReplacementLayers(IEnumerable<CardPoolAssetReplacementLayer> layers, out CardPoolAssetProfile mergedProfile)
	{
		List<CardPoolAssetReplacementLayer> list = layers.ToList();
		if (list.Count == 0)
