		for (int num = 1; num < list.Count; num++)
		{
			cardPoolAssetProfile = CardPoolAssetProfiles.Merge(cardPoolAssetProfile, list[num].Profile);
		}
		mergedProfile = cardPoolAssetProfile;
		return true;
	}

