	internal static IReadOnlyList<CharacterAssetReplacementLayerSnapshot> GetCharacterAssetReplacementLayerSnapshots()
	{
		using (SyncRoot.EnterScope())
		{
			List<CharacterAssetReplacementLayerSnapshot> list = new List<CharacterAssetReplacementLayerSnapshot>();
			string key;
			CharacterAssetReplacementLayer value;
			foreach (KeyValuePair<string, CharacterAssetReplacementLayer> item in RegisteredGlobalCharacterAssetReplacementsByMod)
			{
				item.Deconstruct(out key, out value);
				string modId = key;
				CharacterAssetReplacementLayer characterAssetReplacementLayer = value;
				list.Add(new CharacterAssetReplacementLayerSnapshot("global", "*", modId, characterAssetReplacementLayer.WriteOrder, characterAssetReplacementLayer.Profile));
			}
			foreach (KeyValuePair<string, Dictionary<string, CharacterAssetReplacementLayer>> item2 in RegisteredCharacterAssetReplacementsByEntry)
			{
				item2.Deconstruct(out key, out var value2);
				string characterEntry = key;
				foreach (KeyValuePair<string, CharacterAssetReplacementLayer> item3 in value2)
				{
					item3.Deconstruct(out key, out value);
					string modId2 = key;
					CharacterAssetReplacementLayer characterAssetReplacementLayer2 = value;
					list.Add(new CharacterAssetReplacementLayerSnapshot("character", characterEntry, modId2, characterAssetReplacementLayer2.WriteOrder, characterAssetReplacementLayer2.Profile));
				}
			}
			list.Sort((CharacterAssetReplacementLayerSnapshot x, CharacterAssetReplacementLayerSnapshot y) => x.WriteOrder.CompareTo(y.WriteOrder));
			return list;
		}
	}

	internal static IReadOnlyList<CharacterAssetReplacementResolvedPropertySnapshot> GetCharacterAssetReplacementResolvedPropertySnapshots()
	{
		using (SyncRoot.EnterScope())
		{
			List<CharacterAssetReplacementResolvedPropertySnapshot> list = new List<CharacterAssetReplacementResolvedPropertySnapshot>();
			string[] array = RegisteredCharacterAssetReplacementsByEntry.Keys.OrderBy<string, string>((string x) => x, StringComparer.OrdinalIgnoreCase).ToArray();
			foreach (string characterEntry in array)
			{
				list.AddRange(GetResolvedPropertiesForEntry(characterEntry));
			}
			return list;
		}
	}

