	private bool TryRemoveCharacterAssetReplacementForKey(string dictionaryKey)
	{
		if (!RegisteredCharacterAssetReplacementsByEntry.TryGetValue(dictionaryKey, out Dictionary<string, CharacterAssetReplacementLayer> value))
