	private static bool TryMergeCharacterAssetReplacementLayers(IEnumerable<CharacterAssetReplacementLayer> layers, out CharacterAssetProfile mergedProfile)
	{
		List<CharacterAssetReplacementLayer> list = layers.ToList();
		if (list.Count == 0)
		{
			mergedProfile = CharacterAssetProfile.Empty;
			return false;
		}
		list.Sort((CharacterAssetReplacementLayer x, CharacterAssetReplacementLayer y) => x.WriteOrder.CompareTo(y.WriteOrder));
		CharacterAssetProfile characterAssetProfile = list[0].Profile;
		for (int num = 1; num < list.Count; num++)
		{
			characterAssetProfile = CharacterAssetProfiles.Merge(characterAssetProfile, list[num].Profile);
		}
		mergedProfile = characterAssetProfile;
		return true;
	}

	private static List<CharacterAssetReplacementResolvedPropertySnapshot> GetResolvedPropertiesForEntry(string characterEntry)
	{
		List<CharacterAssetReplacementResolvedPropertySnapshot> list = new List<CharacterAssetReplacementResolvedPropertySnapshot>();
		RegisteredCharacterAssetReplacementsByEntry.TryGetValue(characterEntry, out Dictionary<string, CharacterAssetReplacementLayer> value);
		(string, CharacterAssetReplacementLayer)[] orderedLayers = (from kv in RegisteredGlobalCharacterAssetReplacementsByMod
			select (ModId: kv.Key, Layer: kv.Value) into x
			orderby x.Layer.WriteOrder
			select x).ToArray();
		(string, CharacterAssetReplacementLayer)[] orderedLayers2 = ((value == null) ? Array.Empty<(string, CharacterAssetReplacementLayer)>() : (from kv in value
			select (ModId: kv.Key, Layer: kv.Value) into x
			orderby x.Layer.WriteOrder
			select x).ToArray());
		CharacterAssetPathField[] characterAssetPathFields = CharacterAssetPathFields;
		foreach (CharacterAssetPathField field in characterAssetPathFields)
		{
			CharacterAssetReplacementResolvedPropertySnapshot resolved2;
			if (TryResolveFieldSource(characterEntry, field, orderedLayers2, "character", out var resolved))
			{
				list.Add(resolved);
			}
			else if (TryResolveFieldSource(characterEntry, field, orderedLayers, "global", out resolved2))
			{
				list.Add(resolved2);
			}
		}
		return list;
	}

	private static bool TryResolveFieldSource(string characterEntry, CharacterAssetPathField field, IEnumerable<(string ModId, CharacterAssetReplacementLayer Layer)> orderedLayers, string scope, out CharacterAssetReplacementResolvedPropertySnapshot resolved)
	{
		foreach (var item in orderedLayers.Reverse())
		{
			string value = field.Selector(item.Layer.Profile);
			if (!string.IsNullOrWhiteSpace(value))
			{
				resolved = new CharacterAssetReplacementResolvedPropertySnapshot(characterEntry, field.Name, value, scope, item.ModId, item.Layer.WriteOrder);
				return true;
			}
		}
		resolved = default(CharacterAssetReplacementResolvedPropertySnapshot);
		return false;
	}

