	///         尝试构建为 <paramref name="characterEntry" /> 注册的编程式所属视觉配置。
	///     </para>
	/// </summary>
	internal static bool TryBuildProgrammaticCharacterOwnedVisualProfile(string characterEntry, out CharacterAssetProfile assetProfile)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(characterEntry, "characterEntry");
		string key = NormalizeCharacterAssetEntryKey(characterEntry);
		using (SyncRoot.EnterScope())
		{
			if (CharacterOwnedVisualProgrammaticByCharacterEntry.TryGetValue(key, out Dictionary<string, CharacterOwnedVisualProgrammaticLayer> value) && value.Count != 0)
			{
				return TryMergeCharacterOwnedVisualProgrammaticLayers(value.Values, out assetProfile);
			}
			assetProfile = CharacterAssetProfile.Empty;
			return false;
		}
	}

	private static bool TryMergeCharacterOwnedVisualProgrammaticLayers(IEnumerable<CharacterOwnedVisualProgrammaticLayer> layers, out CharacterAssetProfile mergedProfile)
	{
		List<CharacterOwnedVisualProgrammaticLayer> list = layers.ToList();
		if (list.Count == 0)
		{
			mergedProfile = CharacterAssetProfile.Empty;
			return false;
		}
		list.Sort((CharacterOwnedVisualProgrammaticLayer x, CharacterOwnedVisualProgrammaticLayer y) => x.WriteOrder.CompareTo(y.WriteOrder));
		CharacterAssetProfile characterAssetProfile = list[0].Profile;
		for (int num = 1; num < list.Count; num++)
		{
			characterAssetProfile = CharacterAssetProfiles.Merge(characterAssetProfile, list[num].Profile);
		}
		mergedProfile = characterAssetProfile;
		return true;
	}

