	private void RegisterCharacterOwnedVisualProgrammaticLayer(string characterEntry, CharacterAssetProfile fragment)
	{
		string text = NormalizeCharacterAssetEntryKey(characterEntry);
		using (SyncRoot.EnterScope())
		{
			if (!CharacterOwnedVisualProgrammaticByCharacterEntry.TryGetValue(text, out Dictionary<string, CharacterOwnedVisualProgrammaticLayer> value))
			{
				value = new Dictionary<string, CharacterOwnedVisualProgrammaticLayer>(StringComparer.OrdinalIgnoreCase);
				CharacterOwnedVisualProgrammaticByCharacterEntry[text] = value;
			}
			_characterOwnedVisualProgrammaticWriteOrder++;
			long characterOwnedVisualProgrammaticWriteOrder = _characterOwnedVisualProgrammaticWriteOrder;
			if (value.TryGetValue(ModId, out var value2))
			{
				CharacterAssetProfile profile = CharacterAssetProfiles.Merge(value2.Profile, fragment);
				value[ModId] = new CharacterOwnedVisualProgrammaticLayer(profile, characterOwnedVisualProgrammaticWriteOrder);
			}
			else
			{
				value[ModId] = new CharacterOwnedVisualProgrammaticLayer(fragment, characterOwnedVisualProgrammaticWriteOrder);
			}
		}
		ModCharacterOwnedVisualOverrideHelper.InvalidateCachesForCharacterEntry(text);
		RuntimeAssetRefreshCoordinator.Request(RuntimeAssetRefreshScope.Cards | RuntimeAssetRefreshScope.Relics | RuntimeAssetRefreshScope.Potions);
		_logger.Info($"[Content] Programmatic owned visual override for character '{text}' ({ModId}).", 1);
	}

