	/// <summary>
	///     <para xml:lang="en">Gets the registry for <paramref name="modId" />, creating it on first use.</para>
	///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 的注册表；首次使用时会创建该实例。</para>
	/// </summary>
	public static ModContentRegistry For(string modId)
	{
		ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
		using (SyncRoot.EnterScope())
		{
			if (Registries.TryGetValue(modId, out ModContentRegistry value))
			{
				return value;
			}
			value = new ModContentRegistry(modId);
			Registries[modId] = value;
			return value;
		}
	}

