	/// <summary>
	///     <para xml:lang="en">
	///         Registers a mutually exclusive modifier group in the patched
	///         <see cref="P:MegaCrit.Sts2.Core.Models.ModelDb.MutuallyExclusiveModifiers" /> list.
	///     </para>
	///     <para xml:lang="zh-CN">注册互斥修正项组，使其纳入修补后的 <see cref="P:MegaCrit.Sts2.Core.Models.ModelDb.MutuallyExclusiveModifiers" /> 列表。</para>
	/// </summary>
	public void RegisterMutuallyExclusiveModifierGroup(IReadOnlyList<Type> modifierTypes)
	{
		ArgumentNullException.ThrowIfNull(modifierTypes, "modifierTypes");
		if (modifierTypes.Count < 2)
		{
			throw new ArgumentException("At least two modifier types are required for a mutually exclusive group.", "modifierTypes");
		}
		HashSet<Type> hashSet = new HashSet<Type>();
		foreach (Type modifierType in modifierTypes)
		{
			EnsureModelType(modifierType, typeof(ModifierModel), "modifierTypes");
			hashSet.Add(modifierType);
		}
		if (hashSet.Count < 2)
		{
			throw new ArgumentException("At least two distinct modifier types are required for a mutually exclusive group.", "modifierTypes");
		}
		EnsureMutable("register mutually exclusive modifier group");
		foreach (Type item in hashSet)
		{
			PrimeOwnedType(item);
			RegistrationConflictDetector.ThrowIfModelIdConflicts(item);
		}
		using (SyncRoot.EnterScope())
		{
			RegisteredMutuallyExclusiveModifierGroups.Add(hashSet);
		}
		_logger.Info("[Content] Registered mutually exclusive modifier group: " + string.Join(", ", hashSet.Select((Type t) => t.Name)), 1);
	}

