	internal static void FreezeRegistrations(string reason)
	{
		//IL_00bf: Unknown result type (might be due to invalid IL or missing references)
		using (SyncRoot.EnterScope())
		{
			if (IsFrozen)
			{
				return;
			}
			StartupContentCache.FinishRegistration();
			IsFrozen = true;
			foreach (ModContentRegistry value in Registries.Values)
			{
				value._freezeReason = reason;
			}
		}
		ContentSourceHoverTipFactory.FreezeRegistrations();
		ResolvedModelCache.MarkFrozen();
		foreach (ModContentRegistry value2 in Registries.Values)
		{
			value2._logger.Info("[Content] Content registration is now frozen (" + reason + ").", 1);
		}
		RitsuLibFramework.PublishLifecycleEvent<ContentRegistrationClosedEvent>(new ContentRegistrationClosedEvent(reason, DateTimeOffset.UtcNow), "ContentRegistrationClosedEvent");
	}

	internal static void ValidateFrozenModelReferences()
	{
		ContentModelReference[] array;
		using (SyncRoot.EnterScope())
		{
			List<ContentModelReference> list = new List<ContentModelReference>();
			AddMany(list, RegisteredPoolContent.SelectMany<(Type, Type), ContentModelReference>(((Type PoolType, Type ModelType) entry) => new ContentModelReference[2]
			{
				new ContentModelReference(entry.PoolType, typeof(AbstractModel), "registered pool"),
				new ContentModelReference(entry.ModelType, typeof(AbstractModel), "registered pool content")
			}));
			AddMany(list, RegisteredCharacterStarterContent.SelectMany((CharacterStarterRegistration entry) => new ContentModelReference[2]
			{
				new ContentModelReference(entry.CharacterType, typeof(CharacterModel), "registered starter character"),
				new ContentModelReference(entry.ModelType, typeof(AbstractModel), $"registered starter {entry.Kind}")
			}));
			AddMany(list, RegisteredCharacters.Select((Type type) => new ContentModelReference(type, typeof(CharacterModel), "registered character")));
			AddMany(list, RegisteredActs.Select((Type type) => new ContentModelReference(type, typeof(ActModel), "registered act")));
			AddMany(list, RegisteredMonsters.Select((Type type) => new ContentModelReference(type, typeof(MonsterModel), "registered monster")));
			AddMany(list, RegisteredPowers.Select((Type type) => new ContentModelReference(type, typeof(PowerModel), "registered power")));
			AddMany(list, RegisteredOrbs.Select((Type type) => new ContentModelReference(type, typeof(OrbModel), "registered orb")));
			AddMany(list, RegisteredModelCapabilities.Select((Type type) => new ContentModelReference(type, typeof(ModelCapability), "registered model capability")));
			AddMany(list, RegisteredEnchantments.Select((Type type) => new ContentModelReference(type, typeof(EnchantmentModel), "registered enchantment")));
			AddMany(list, RegisteredAfflictions.Select((Type type) => new ContentModelReference(type, typeof(AfflictionModel), "registered affliction")));
			AddMany(list, RegisteredAchievements.Select((Type type) => new ContentModelReference(type, typeof(AchievementModel), "registered achievement")));
			AddMany(list, RegisteredSingletons.Select((Type type) => new ContentModelReference(type, typeof(SingletonModel), "registered singleton")));
			AddMany(list, RegisteredSharedCardPools.Select((Type type) => new ContentModelReference(type, typeof(CardPoolModel), "registered shared card pool")));
			AddMany(list, RegisteredSharedRelicPools.Select((Type type) => new ContentModelReference(type, typeof(RelicPoolModel), "registered shared relic pool")));
			AddMany(list, RegisteredSharedPotionPools.Select((Type type) => new ContentModelReference(type, typeof(PotionPoolModel), "registered shared potion pool")));
			AddMany(list, RegisteredGoodModifiers.Select((ModifierRegistration registration) => new ContentModelReference(registration.ModifierType, typeof(ModifierModel), "registered good modifier")));
			AddMany(list, RegisteredBadModifiers.Select((ModifierRegistration registration) => new ContentModelReference(registration.ModifierType, typeof(ModifierModel), "registered bad modifier")));
			AddMany(list, RegisteredSharedEvents.Select((Type type) => new ContentModelReference(type, typeof(EventModel), "registered shared event")));
			AddMany(list, RegisteredSharedAncients.Select((Type type) => new ContentModelReference(type, typeof(AncientEventModel), "registered shared ancient")));
			AddScoped(list, RegisteredActEncounters, typeof(ActModel), typeof(EncounterModel), "registered act encounter");
			AddMany(list, RegisteredGlobalEncounters.Select((Type type) => new ContentModelReference(type, typeof(EncounterModel), "registered global encounter")));
			AddScoped(list, RegisteredActEvents, typeof(ActModel), typeof(EventModel), "registered act event");
			AddScoped(list, RegisteredActAncients, typeof(ActModel), typeof(AncientEventModel), "registered act ancient");
			array = list.DistinctBy((ContentModelReference reference) => (ModelType: reference.ModelType, ExpectedBaseType: reference.ExpectedBaseType, Description: reference.Description)).ToArray();
		}
		ContentModelReference[] array2 = array;
		for (int num = 0; num < array2.Length; num++)
		{
			ContentModelReference contentModelReference = array2[num];
			TryGetOwnerModId(contentModelReference.ModelType, out string modId);
			RegistrationFreezeDiagnostics.WarnMissingModelType("Content", modId, contentModelReference.Description, contentModelReference.ModelType, contentModelReference.ExpectedBaseType);
		}
