		}
		static void AddScoped(List<ContentModelReference> list2, Dictionary<Type, HashSet<Type>> registry, Type expectedScopeType, Type expectedModelType, string description)
		{
			foreach (var (modelType, source) in registry)
			{
				list2.Add(new ContentModelReference(modelType, expectedScopeType, description + " scope"));
				list2.AddRange(source.Select((Type modelType2) => new ContentModelReference(modelType2, expectedModelType, description)));
			}
		}
	}

