	/// <summary>
	///     <para xml:lang="en">
	///         Gets a snapshot of registered model types with ownership, resolved ID, and public-entry diagnostics.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         获取已注册模型类型的快照，其中包含所有者、已解析 ID 和公共条目诊断信息。
	///     </para>
	/// </summary>
	public static ModContentRegisteredTypeSnapshot[] GetRegisteredTypeSnapshots()
	{
		using (SyncRoot.EnterScope())
		{
			return RegisteredTypeOwners.OrderBy<KeyValuePair<Type, string>, string>((KeyValuePair<Type, string> kvp) => kvp.Value, StringComparer.OrdinalIgnoreCase).ThenBy<KeyValuePair<Type, string>, string>((KeyValuePair<Type, string> kvp) => kvp.Key.FullName, StringComparer.Ordinal).Select(delegate(KeyValuePair<Type, string> kvp)
			{
				Type key = kvp.Key;
				string value = kvp.Value;
				ModelId modelDbId = TryGetModelDbId(key);
				bool hasExplicitOverride;
				string expectedPublicEntry = TryGetExpectedPublicEntry(key, value, out hasExplicitOverride);
				string typeNamePublicEntry = TryGetTypeNamePublicEntry(key);
				return new ModContentRegisteredTypeSnapshot(value, key, modelDbId, expectedPublicEntry, hasExplicitOverride, typeNamePublicEntry);
			})
				.ToArray();
		}
		static string? TryGetExpectedPublicEntry(Type modelType, string modId, out bool hasExplicitOverride)
		{
			if (FixedPublicEntryOverrides.TryGetValue(modelType, out string value))
			{
				hasExplicitOverride = true;
				return value;
			}
			try
			{
				hasExplicitOverride = false;
				return GetFixedPublicEntry(modId, modelType);
			}
			catch
			{
				hasExplicitOverride = false;
				return null;
			}
		}
		static ModelId? TryGetModelDbId(Type modelType)
		{
			try
			{
				return ModelDb.GetId(modelType);
			}
			catch
			{
				return null;
			}
		}
		static string? TryGetTypeNamePublicEntry(Type modelType)
		{
			try
			{
				string text = NormalizePublicStem(modelType.Name);
				return NormalizePublicStem(ModelDb.GetCategory(modelType)) + "_" + text;
			}
			catch
			{
				return null;
			}
		}
	}

