	/// <summary>
	///     <para xml:lang="en">
	///         Injects RitsuLib-registered types from <see cref="P:System.Reflection.Assembly.IsDynamic" /> assemblies into
	///         <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> before <c>Init</c> finishes populating <c>_contentById</c>. The game's subtype
	///         scan discovers static mod DLL types, but not Reflection.Emit placeholder types.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <c>Init</c> 完成填充 <c>_contentById</c> 前，将位于 <see cref="P:System.Reflection.Assembly.IsDynamic" />
	///         程序集中的 RitsuLib 注册类型注入 <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />。游戏的子类型扫描能够发现静态模组
	///         DLL 中的类型，但无法发现通过 Reflection.Emit 生成的占位类型。
	///     </para>
	/// </summary>
	internal static void InjectDynamicRegisteredModels()
	{
		Type[] array;
		using (SyncRoot.EnterScope())
		{
			array = (from t in RegisteredPoolContent.SelectMany<(Type, Type), Type>(((Type PoolType, Type ModelType) entry) => new Type[2] { entry.PoolType, entry.ModelType }).Concat(RegisteredCharacters).Concat(RegisteredActs)
					.Concat(RegisteredMonsters)
					.Concat(RegisteredPowers)
					.Concat(RegisteredOrbs)
					.Concat(RegisteredModelCapabilities)
					.Concat(RegisteredEnchantments)
					.Concat(RegisteredAfflictions)
					.Concat(RegisteredAchievements)
					.Concat(RegisteredSingletons)
					.Concat(RegisteredSharedCardPools)
					.Concat(RegisteredSharedRelicPools)
					.Concat(RegisteredSharedPotionPools)
					.Concat(RegisteredGoodModifiers.Select((ModifierRegistration registration) => registration.ModifierType))
					.Concat(RegisteredBadModifiers.Select((ModifierRegistration registration) => registration.ModifierType))
					.Concat(RegisteredMutuallyExclusiveModifierGroups.SelectMany((HashSet<Type> @group) => @group))
					.Concat(RegisteredSharedEvents)
					.Concat(RegisteredSharedAncients)
					.Concat(RegisteredActEncounters.Values.SelectMany((HashSet<Type> set) => set))
					.Concat(RegisteredGlobalEncounters)
					.Concat(RegisteredActEvents.Values.SelectMany((HashSet<Type> set) => set))
					.Concat(RegisteredActAncients.Values.SelectMany((HashSet<Type> set) => set))
					.Distinct()
				where t.Assembly.IsDynamic
				select t).OrderBy<Type, string>((Type t) => t.FullName ?? t.Name, StringComparer.Ordinal).ToArray();
		}
		Type[] array2 = array;
		for (int num = 0; num < array2.Length; num++)
		{
			ModelDb.Inject(array2[num]);
		}
	}

	private void RegisterPoolModel(Type poolType, Type modelType, Type expectedPoolBaseType, Type expectedModelBaseType, string contentKind, ModelPublicEntryOptions publicEntry = default(ModelPublicEntryOptions))
	{
		EnsureModelType(poolType, expectedPoolBaseType, "poolType");
		EnsureModelType(modelType, expectedModelBaseType, "modelType");
		EnsureMutable($"register {contentKind} '{modelType.Name}' into pool '{poolType.Name}'");
		PrimeOwnedType(modelType);
		ApplyFixedPublicEntryForModel(modelType, publicEntry);
		RegistrationConflictDetector.ThrowIfModelIdConflicts(poolType);
		RegistrationConflictDetector.ThrowIfModelIdConflicts(modelType);
		string value = FormatModelForLog(modelType);
		using (SyncRoot.EnterScope())
		{
			if (RegisteredPoolContent.Contains((poolType, modelType)))
			{
				_logger.Debug($"[Content] Skipping duplicate {contentKind} registration: {value} -> {poolType.Name}", 1);
				return;
			}
			ModHelper.AddModelToPool(poolType, modelType);
			RegisteredPoolContent.Add((poolType, modelType));
			RememberOwner(modelType);
		}
		_logger.Info($"[Content] Registered {contentKind}: {value} -> {poolType.Name}", 1);
	}

	private void RegisterCharacterStarterModel(Type characterType, Type modelType, Type expectedModelBaseType, CharacterStarterContentKind kind, int count, int order)
	{
		if (count <= 0)
		{
			throw new ArgumentOutOfRangeException("count", count, "Starter content count must be positive.");
		}
		EnsureModelType(characterType, typeof(CharacterModel), "characterType");
