	private static bool MatchesRegisteredStarterCharacter(Type registeredCharacterType, Type runtimeCharacterType)
	{
		if (registeredCharacterType == runtimeCharacterType)
		{
			return true;
		}
		if (!registeredCharacterType.IsAssignableFrom(runtimeCharacterType))
		{
			return false;
		}
		return registeredCharacterType != typeof(CharacterModel);
	}

	private static string FormatModelForLog(Type modelType)
	{
		if (!TryGetFixedPublicEntry(modelType, out string entry))
		{
			return modelType.Name;
		}
		return modelType.Name + " (id=" + entry + ")";
	}

	private static Type[] GetRegisteredCharacterStarterTypes(Type characterType, CharacterStarterContentKind kind)
	{
		ArgumentNullException.ThrowIfNull(characterType, "characterType");
		using (SyncRoot.EnterScope())
		{
			return (from x in RegisteredCharacterStarterContent.Select((CharacterStarterRegistration entry, int index) => new { entry, index })
				orderby x.entry.Order, x.index
				where x.entry.Kind == kind && MatchesRegisteredStarterCharacter(x.entry.CharacterType, characterType)
				select x).SelectMany(x => Enumerable.Repeat(x.entry.ModelType, x.entry.Count)).ToArray();
		}
	}

