	private void ApplyFixedPublicEntryForModel(Type modelType, ModelPublicEntryOptions options)
	{
		if (options.Kind == ModelPublicEntryKind.FromTypeName)
		{
			return;
		}
		ModelId id = ModelDb.GetId(modelType);
		string text = options.Kind switch
		{
			ModelPublicEntryKind.Stem => $"{NormalizePublicStem(ModId)}_{NormalizePublicStem(ModelDb.GetCategory(modelType))}_{NormalizePublicStem(options.Value)}", 
			ModelPublicEntryKind.FullEntry => NormalizeFullPublicEntry(options.Value), 
			_ => throw new ArgumentOutOfRangeException("options", options.Kind, null), 
		};
		using (SyncRoot.EnterScope())
		{
			if (FixedPublicEntryOverrides.TryGetValue(modelType, out string value))
			{
				if (!string.Equals(value, text, StringComparison.Ordinal))
				{
					throw new InvalidOperationException($"Cannot change fixed public entry for '{modelType.FullName}' from '{value}' to '{text}'.");
				}
				return;
			}
			FixedPublicEntryOverrides[modelType] = text;
		}
		RegistrationConflictDetector.UpdateModelIdIndex(modelType, id, ModelDb.GetId(modelType));
	}

	private string ResolveModelCapabilityId(Type capabilityType, ModelPublicEntryOptions options)
	{
		return options.Kind switch
		{
			ModelPublicEntryKind.FromTypeName => GetQualifiedModelCapabilityId(ModId, capabilityType.Name), 
			ModelPublicEntryKind.Stem => GetQualifiedModelCapabilityId(ModId, options.Value), 
			ModelPublicEntryKind.FullEntry => NormalizeFullPublicEntry(options.Value), 
			_ => throw new ArgumentOutOfRangeException("options", options.Kind, null), 
		};
	}

