	private void RememberOwner(Type type)
	{
		if (RegisteredTypeOwners.TryGetValue(type, out string value) && !string.Equals(value, ModId, StringComparison.OrdinalIgnoreCase))
		{
			throw new InvalidOperationException($"Model type '{type.FullName}' is already owned by mod '{value}' and cannot be registered by '{ModId}'.");
		}
		RegisteredTypeOwners[type] = ModId;
	}

	private void PrimeOwnedType(Type type)
	{
		ModelId id = ModelDb.GetId(type);
		using (SyncRoot.EnterScope())
		{
			RememberOwner(type);
		}
		RegistrationConflictDetector.UpdateModelIdIndex(type, id, ModelDb.GetId(type));
	}

